import{_ as n,C as d,o as s,c,j as t,a as o,E as a,ag as l}from"./chunks/framework.HG0H2VLS.js";const x=JSON.parse('{"title":"Modal","description":"","frontmatter":{},"headers":[],"relativePath":"patterns/modal.md","filePath":"patterns/modal.md"}'),h={name:"patterns/modal.md"},p={id:"modal",tabindex:"-1"};function m(g,e,u,b,f,w){const r=d("Badge"),i=d("ComponentDemo");return s(),c("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-modal",tabindex:"-1"},[o("title: Modal "),t("a",{class:"header-anchor",href:"#title-modal","aria-label":'Permalink to "title: Modal"'},"​")],-1)),t("h1",p,[e[0]||(e[0]=o("Modal ",-1)),a(r,{type:"info",text:"Design System"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#modal","aria-label":'Permalink to "Modal <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,[t("strong",null,[o("gained "),t("code",null,"__title-block"),o(" + "),t("code",null,"__subtitle"),o(" 2026-08-27")]),o(" (Figma's ModalHeader has a formal "),t("code",null,"subText"),o(" property; purely additive — no existing modal has a subtitle) and the "),t("strong",null,"compact values folded into its existing 639px block"),o(` (body 24→16, title 18→16, title-block gap 6→4, subtitle 14→13), so figma-notes' "Figma defines no mobile modal" is now superseded`)])],-1)),a(i,{src:"/demos/src/patterns/Modal/Modal.html"}),e[6]||(e[6]=l('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Dialog pattern for alerts, confirmations, forms, feedback, and scrollable content. Composes Button, Input, Textarea, and Checkbox components.</p><h2 id="figma-reference" tabindex="-1">Figma Reference <a class="header-anchor" href="#figma-reference" aria-label="Permalink to &quot;Figma Reference&quot;">​</a></h2><ul><li><strong>Component set:</strong> <a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=2464-763" target="_blank" rel="noreferrer">Modal</a></li><li><strong>File:</strong> Affino AI — Design System (<code>Lus07xi8pPXLN87sQIyrEt</code>)</li></ul><h2 id="token-usage" tabindex="-1">Token Usage <a class="header-anchor" href="#token-usage" aria-label="Permalink to &quot;Token Usage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th></tr></thead><tbody><tr><td>Background</td><td><code>--ai-surface-primary</code></td></tr><tr><td>Border radius</td><td><code>--ai-radius-lg</code></td></tr><tr><td>Shadow</td><td><code>0 0 20px rgba(0,0,0,0.05), 0 2px 2px rgba(0,0,0,0.1)</code></td></tr><tr><td>Header/footer padding</td><td><code>--ai-spacing-5</code> (v) / <code>--ai-spacing-6</code> (h)</td></tr><tr><td>Header/footer border</td><td><code>--ai-border-secondary</code></td></tr><tr><td>Body padding</td><td><code>--ai-spacing-6</code></td></tr><tr><td>Body paragraph gap</td><td><code>--ai-spacing-5</code></td></tr><tr><td>Title font</td><td><code>--ai-font-title</code> / <code>--ai-font-fixed-md</code> / <code>--ai-font-semibold</code></td></tr><tr><td>Title color</td><td><code>--ai-text-primary</code></td></tr><tr><td>Body text</td><td><code>--ai-font-body</code> / <code>--ai-font-fixed-xs</code> / <code>--ai-text-secondary</code></td></tr><tr><td>Footer button gap</td><td><code>--ai-spacing-3</code></td></tr><tr><td>Close button size</td><td><code>--ai-spacing-7</code> (32px)</td></tr><tr><td>Close icon size</td><td><code>--ai-icon-size-md</code> (20px)</td></tr><tr><td>Confirmation icon wrap</td><td>56px circle, <code>--ai-surface-minimal</code> bg</td></tr><tr><td>Confirmation icon</td><td><code>--ai-icon-size-lg</code>, <code>--ai-text-error</code></td></tr><tr><td>Feedback header gap</td><td><code>--ai-spacing-4</code></td></tr><tr><td>Feedback icon circle</td><td><code>--ai-spacing-8</code> (40px), <code>--ai-radius-full</code></td></tr><tr><td>Feedback positive bg</td><td><code>#dcfeec</code> (Aqua/50 — primitive, approved)</td></tr><tr><td>Feedback positive icon</td><td><code>--ai-surface-success</code></td></tr><tr><td>Feedback negative bg</td><td><code>#fef3f3</code> (Red/50 — primitive, approved)</td></tr><tr><td>Feedback negative icon</td><td><code>--ai-text-error</code></td></tr><tr><td>Checkbox list gap</td><td><code>--ai-spacing-4</code></td></tr></tbody></table><h2 id="responsive" tabindex="-1">Responsive <a class="header-anchor" href="#responsive" aria-label="Permalink to &quot;Responsive&quot;">​</a></h2><p><strong>Superseded 2026-08-27.</strong> Figma now DOES define a compact modal — see <em>Header / Body / Footer are their own component sets</em> below — and the Seating Planner&#39;s create-plan modal (<code>3515:228092</code> / <code>3515:212739</code>) is the first frame to specify it. The rules below were extended for it.</p><p>Original note: Figma defines no mobile modal variant. One responsive rule exists in code:</p><table tabindex="0"><thead><tr><th>Breakpoint</th><th>Rule</th><th>Origin</th></tr></thead><tbody><tr><td><code>max-width: 639px</code> (below <code>--ai-bp-sm</code>)</td><td><code>.modal__header</code> / <code>.modal__footer</code> padding → <code>var(--ai-spacing-4) var(--ai-spacing-5)</code> (from <code>--ai-spacing-5</code> / <code>--ai-spacing-6</code>)</td><td>Added 2026-07-27 during the EventPicker build, then applied to <strong>all</strong> modals by request</td></tr></tbody></table><p><code>.modal--confirm .modal__footer</code> is unaffected — it is more specific and keeps its intentionally borderless, centred <code>0 var(--ai-spacing-6) var(--ai-spacing-6)</code> padding. <code>.modal__body</code> padding is also unchanged at every width.</p><h2 id="overlay-scrim-—-per-theme" tabindex="-1">Overlay scrim — per theme <a class="header-anchor" href="#overlay-scrim-—-per-theme" aria-label="Permalink to &quot;Overlay scrim — per theme&quot;">​</a></h2><p><code>.modal-overlay</code> supplies the scrim for every modal in the system. Its colour and its opacity move on <strong>two independent axes</strong> (designer, 2026-08-26):</p><table tabindex="0"><thead><tr><th></th><th>light</th><th>dark</th></tr></thead><tbody><tr><td>default / CC</td><td><code>rgba(15, 23, 42, 0.5)</code> — navy</td><td><code>rgba(15, 23, 42, 0.85)</code></td></tr><tr><td>chat</td><td><code>rgba(0, 0, 0, 0.5)</code> — black</td><td><code>rgba(0, 0, 0, 0.85)</code></td></tr></tbody></table><p><strong>Colour comes from the surface.</strong> <code>#0F172A</code> navy for the default, dark, CC-light and CC-dark themes — this is what Figma draws (Seating Planner overlays <code>3515:176055</code> light / <code>3515:176080</code> dark), and black read as too harsh a veil against those slate greys. The <strong>chat</strong> surfaces keep black, which suits their own near-neutral palette — <code>--cc-ui-primary-bg</code> is <code>#ececed</code> / <code>#131316</code> there, not the navy-tinted slate the CC and default themes use.</p><p><strong>Opacity comes from the theme</strong>, regardless of surface: 0.5 light, 0.85 dark. A 50% veil over an already-dark page barely separates the dialog from it, so the density has to rise to keep the modal legible. The dark value was read off Figma&#39;s own dark frame rather than assumed.</p><p><strong>The selectors mirror the token files exactly</strong>, so a modal is always scrimmed to match the theme it is actually rendered in:</p><table tabindex="0"><thead><tr><th>Theme</th><th>Token file selector</th><th>Scrim rule</th></tr></thead><tbody><tr><td>light</td><td><code>:root</code></td><td><code>.modal-overlay</code></td></tr><tr><td>dark</td><td><code>[data-theme=&quot;dark&quot;]</code></td><td><code>[data-theme=&quot;dark&quot;] .modal-overlay</code></td></tr><tr><td>CC light</td><td><code>[data-brand=&quot;cc&quot;]</code></td><td>— inherits the default navy</td></tr><tr><td>CC dark</td><td><code>[data-brand=&quot;cc&quot;][data-theme=&quot;dark&quot;]</code></td><td>— inherits the dark navy</td></tr><tr><td>chat light</td><td><code>[data-surface=&quot;chat&quot;]</code></td><td><code>[data-surface=&quot;chat&quot;] .modal-overlay</code></td></tr><tr><td>chat dark</td><td><code>[data-theme=&quot;dark&quot;] [data-surface=&quot;chat&quot;]</code></td><td>same, prefixed</td></tr></tbody></table><p><code>data-theme</code> and <code>data-brand</code> sit on <code>&lt;html&gt;</code>; <strong><code>data-surface</code> sits on <code>&lt;body&gt;</code></strong>, which is why the chat rules are descendant selectors — the same shape <code>tokens-chat-dark.css</code> itself uses. CC needs no rule of its own: both CC themes take the default navy.</p><p>Specificity resolves the overlap without relying on source order — chat-dark is three attributes deep, so it beats both the plain dark rule and the plain chat rule.</p><blockquote><p><strong>This lived in <code>SeatingPlanner.css</code> first</strong> and was promoted here on 2026-08-26, because nothing about it was specific to that screen. Promoting it changed three existing consumers (this demo, ControlScreen, ControlHub) from black to navy in the default themes — intended, not incidental.</p></blockquote><h3 id="token-gap" tabindex="-1">Token gap <a class="header-anchor" href="#token-gap" aria-label="Permalink to &quot;Token gap&quot;">​</a></h3><p><strong>There is no scrim token</strong>, so all four values are raw rgba. <code>#0f172a</code> exists as <code>--cc-header-primary-bg</code> (and dark <code>--cc-ui-primary-bg</code>), but binding a scrim to a header or page background would be a category error, and a hex token cannot carry the alpha anyway. The proper fix is a real <code>--ai-surface-scrim</code> with per-theme values in Figma; until then these are deliberate raw values, not oversights.</p><h2 id="header-body-footer-are-their-own-component-sets" tabindex="-1">Header / Body / Footer are their own component sets <a class="header-anchor" href="#header-body-footer-are-their-own-component-sets" aria-label="Permalink to &quot;Header / Body / Footer are their own component sets&quot;">​</a></h2><p>Discovered 2026-08-27 while building the Seating Planner&#39;s create-plan modal. Modal&#39;s parts have been promoted to component sets of their own, each with a <strong>Size</strong> axis:</p><table tabindex="0"><thead><tr><th>Component</th><th>Set</th><th>Variants</th></tr></thead><tbody><tr><td>ModalHeader</td><td><code>3427:11820</code></td><td><code>Size=Base</code> (<code>3427:11819</code>), <code>Size=sm</code> (<code>3427:11821</code>)</td></tr><tr><td>ModalBody</td><td><code>3427:12224</code></td><td><code>Size=Base</code> (<code>3427:11885</code>), <code>Size=sm</code> (<code>3427:12231</code>)</td></tr><tr><td>Modal Footer</td><td><code>3427:11838</code></td><td><code>Size=Base</code> (<code>3427:11837</code>), <code>Size=sm</code> (<code>3427:11839</code>)</td></tr></tbody></table><p><code>ModalHeader</code> also exposes four properties this component did not express: <strong><code>subText</code></strong>, <strong><code>subTitle</code></strong>, <strong><code>showIcon</code></strong> and <strong><code>size</code></strong>.</p><h3 id="what-was-implemented" tabindex="-1">What was implemented <a class="header-anchor" href="#what-was-implemented" aria-label="Permalink to &quot;What was implemented&quot;">​</a></h3><p><strong><code>subText</code></strong> — as <code>.modal__title-block</code> + <code>.modal__subtitle</code>. The create-plan modal needed it (&quot;New Seating Plan&quot; over the event name). Purely additive: no existing modal has a subtitle, so EventPicker, ControlScreen and ControlHub are untouched, and <code>.modal__title</code> still works as a direct header child.</p><p><strong>The sm values</strong> — folded into the existing <code>max-width: 639px</code> block (body padding → 16, title → 16, title-block gap → 4, subtitle → 13), joining the header/footer padding rule already there.</p><h3 id="what-was-not-and-why-it-matters" tabindex="-1">What was NOT, and why it matters <a class="header-anchor" href="#what-was-not-and-why-it-matters" aria-label="Permalink to &quot;What was NOT, and why it matters&quot;">​</a></h3><ul><li><strong><code>showIcon</code></strong> — a 40px tinted disc with a 20px glyph. Its <code>rgba(48, 203, 144, 0.15)</code> fill is the <em>same already-approved value</em> <code>.modal__header-icon--positive</code> uses, so there is no token question here, only unwritten CSS.</li><li><strong><code>subTitle</code></strong> — a second, inline title beside the first, medium weight with <code>--ai-tracking-3</code>. Distinct from <code>subText</code>, which sits <em>below</em>.</li><li><strong>Base/sm are SIZE VARIANTS, not a breakpoint.</strong> This is the important one. Implementing them as <code>@media (max-width: 639px)</code> reproduces the right values for these screens, but a consumer who wants the compact modal at desktop width cannot ask for it, and a <code>.modal--compact</code> class would be the faithful model. Chosen deliberately (designer, 2026-08-27) as the smaller change; a full ModalHeader/Body/Footer audit is its own job.</li><li><strong>The sm variant&#39;s own padding disagrees with the screens using it.</strong> <code>Size=sm</code> binds <code>py: --ai-spacing-3</code> (8) and a 6px heading gap; the create-plan mobile frames bind <code>py: 12</code> and a 4px gap — which is what Modal&#39;s existing 639px rule already produced. So those frames are not using sm as drawn. Worth resolving before the audit.</li><li><strong><code>.modal</code> shadow and border still differ from Figma.</strong> Figma binds <code>light/shadow-md</code> (<code>--ai-shadow-md</code>) plus a 1px <code>--ai-border-secondary</code>; <code>.modal</code> has neither. Pre-existing, flagged on the Seating Planner screens too.</li><li><strong>The overlay&#39;s mobile padding.</strong> The create-plan mobile frame places its modal 32px from each edge, where <code>.modal-overlay</code> pads <code>--ai-spacing-6</code> (24) — so the modal renders 354 wide against Figma&#39;s 338. Not changed, because overlay padding is shared by every modal.</li></ul><h2 id="two-fixes-2026-08-27" tabindex="-1">Two fixes, 2026-08-27 <a class="header-anchor" href="#two-fixes-2026-08-27" aria-label="Permalink to &quot;Two fixes, 2026-08-27&quot;">​</a></h2><p><strong><code>.modal</code> had no border.</strong> Figma binds a 1px <code>--ai-border-secondary</code> on the Modal root and always had; it was noted as a difference while building the Seating Planner screens and then not acted on. Added for <strong>all</strong> modals. With the global <code>border-box</code> it sits inside the width, so <code>--ai-size-9</code> stays 512px.</p><p><strong><code>.modal__body p</code> was restyling nested paragraphs.</strong> At (0,1,1) it beat any single-class selector, including <code>.input__help</code> (0,1,0) — so the create-plan form&#39;s help lines rendered at 14px/24 instead of Input&#39;s 12px/16. Scoped to <code>.modal__body &gt; p</code>, which is what the rule always meant: it is for the modal&#39;s own body copy. Verified safe — all 36 paragraphs in Modal&#39;s own demo are direct children, and the only nested ones anywhere are the help lines that should never have been caught.</p><h3 id="the-header-type-is-leading-none" tabindex="-1">The header type is <code>leading-none</code> <a class="header-anchor" href="#the-header-type-is-leading-none" aria-label="Permalink to &quot;The header type is `leading-none`&quot;">​</a></h3><p><code>.modal__title</code> used <code>--ai-leading-md</code> (24px) and <code>.modal__subtitle</code> <code>--ai-leading-xs</code> (16px), where Figma&#39;s ModalHeader renders <strong>both</strong> <code>leading-none</code> — its title row is <code>h-[18px]</code> against an 18px font. That made every modal header 8px taller than drawn. Fixed 2026-08-27.</p><p><strong>A unitless <code>1</code>, deliberately, and not <code>0</code></strong> (which was the suggestion). Zero gives the element zero height, so in the header&#39;s flex column the title would contribute nothing and the subtitle would overlap it — the header collapses rather than tightens. Figma&#39;s <code>leading-[0]</code> appears on the text <em>wrapper</em> and is an export artefact of mixed-style containers; <code>leading-none</code> on the paragraph is the real instruction. <code>1</code> also scales, so one rule covers Base and the compact size (18px and 16px title, 14px and 13px subtitle) where a fixed px value would need two — and it stays correct in themes where <code>--ai-font-fixed-md</code> resolves differently, as it does on EventPicker&#39;s page.</p><p>The title has no <code>nowrap</code> or ellipsis, so a long user-supplied name still wraps rather than being clipped; at leading 1 those lines touch but stay legible.</p><p><strong>Token added, gap closed.</strong> There was no ratio token and no <code>--ai-leading-*</code> equal to 18px (the scale is 16/20/24/32/40/48), so <strong><code>--ai-leading-none: 1</code> was added</strong> to <code>FigmaTokens/Typography/{Desktop,Mobile,Minimised}.tokens.json</code> on 2026-08-27 — the designer had already added the Figma variable, so the next export replaces the placeholder variableId.</p><p>That needed a <strong>pipeline fix as well</strong>: <code>dimension/figma-rem</code> converts every <code>$type: &quot;number&quot;</code> token to rem, so a value of <code>1</code> would have exported as <code>0.0625rem</code> (1px) and collapsed every line box using it. The transform now leaves any <code>line height</code> value of 4 or less unitless — detected by magnitude rather than by name, so a future <code>leading-tight: 1.25</code> works too. <strong>This would have bitten the designer&#39;s own upload</strong>, not just the hand-added token.</p><p>Result: the Seating Planner&#39;s create-plan modal now measures <strong>512×506 with a 71px header and a 38px title block — exactly Figma</strong>, having been 562 before this and the two fixes above. Modal&#39;s own demo and EventPicker are unaffected in height, since their headers are driven by the 32px close button rather than by the title.</p><h2 id="the-modal-overflowed-its-overlay-padding-2026-08-27-samsung-s23" tabindex="-1">The modal overflowed its overlay padding (2026-08-27, Samsung S23) <a class="header-anchor" href="#the-modal-overflowed-its-overlay-padding-2026-08-27-samsung-s23" aria-label="Permalink to &quot;The modal overflowed its overlay padding (2026-08-27, Samsung S23)&quot;">​</a></h2><p>Reported: the Select-an-event modal felt too close to the top and bottom of the phone. Measured on the device screenshot — about <strong>5px</strong> of gap where the overlay declares <strong>24</strong>.</p><p><code>.modal</code> had <code>width</code> and <code>max-width</code> but <strong>no height cap</strong>, so it grew to its content height. Being centred in a flex overlay, an item taller than the container overflows equally past the padding on both sides — the padding is not a floor. On a ~543px-tall visible viewport the modal wanted 532, so the 24px gaps collapsed to ~5.</p><p>Fixed with <code>max-block-size: 100%</code> on <code>.modal</code> — <code>100%</code> is the overlay&#39;s content box, so the padding is now respected and the modal shrinks instead. Nothing else was needed for the content: a growable middle region like <code>.event-picker__list</code> already sets <code>overflow-y: auto</code>, which makes its automatic minimum size zero, so it absorbs the reduction and scrolls.</p><p><strong>Overlay padding also raised to 32 at ≤639px.</strong> With the overflow fixed the gap was a correct 24, but the designer&#39;s point stands on a 543px-tall screen. Figma had already implied 32: the create-plan MOBILE frame is 338 wide inside a 402 viewport — a discrepancy recorded in these notes when that screen was built and left alone because nothing depended on it.</p><p><strong>A cascade-order trap worth recording.</strong> That override was first written inside the existing <code>Size=sm</code> <code>@media (max-width: 639px)</code> block at line ~366 — and silently did nothing, because the base <code>.modal-overlay</code> rule sits at line ~391, <em>after</em> it, at equal specificity. Padding stayed 24px; measured, not assumed. The fix was to move the rule below the base declaration rather than raise its specificity, which would have hidden the ordering problem instead of solving it.</p><p>Verified: S23 box (360×543) picker → overlay padding 32, modal 479 of 543, gaps 32/32, inner list scrolling; create-plan → 365 tall, centred with 89 either side; desktop (1400×900) unchanged at 24 with 128px gaps. Zero JS errors throughout.</p><h2 id="variants" tabindex="-1">Variants <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Variants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Node ID</th><th>Type</th></tr></thead><tbody><tr><td>2464:762</td><td>Default</td></tr><tr><td>2464:760</td><td>Small</td></tr><tr><td>2464:761</td><td>Confirmation</td></tr><tr><td>2464:758</td><td>Form</td></tr><tr><td>2464:756</td><td>Large</td></tr><tr><td>2464:757</td><td>Scrollable</td></tr><tr><td>2464:755</td><td>Feedback Positive</td></tr><tr><td>2464:759</td><td>Positive Negative</td></tr></tbody></table><h2 id="css-classes" tabindex="-1">CSS Classes <a class="header-anchor" href="#css-classes" aria-label="Permalink to &quot;CSS Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma Variant</th><th>CSS Class</th></tr></thead><tbody><tr><td>Default (512px)</td><td><code>.modal</code></td></tr><tr><td>Small (384px)</td><td><code>.modal.modal--sm</code></td></tr><tr><td>Large (768px)</td><td><code>.modal.modal--lg</code></td></tr><tr><td>Confirmation (448px)</td><td><code>.modal.modal--confirm</code></td></tr><tr><td>Feedback Positive</td><td><code>.modal.modal--feedback</code> + <code>.modal__header-icon--positive</code></td></tr><tr><td>Positive Negative</td><td><code>.modal.modal--feedback</code> + <code>.modal__header-icon--negative</code></td></tr><tr><td>Form</td><td><code>.modal</code> with <code>.modal__form</code> in body</td></tr><tr><td>Scrollable</td><td><code>.modal</code> with <code>.modal__body--scroll</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Overlay (<code>.modal-overlay</code>) included for interactive demo but is not part of the Figma component — it&#39;s an implementation detail.</li><li>Scrollable body max-height (360px) is a hardcoded layout dimension.</li><li>Confirmation icon wrap size (56px) is a hardcoded layout dimension.</li><li>The Figma source uses flat frames for buttons/textarea/checkbox — the code composes the real components.</li></ul><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=2464-763" target="_blank" rel="noreferrer">Open in Figma</a></p>',57))])}const v=n(h,[["render",m]]);export{x as __pageData,v as default};
